COMMENT ON COLUMN lift_confirmation.review_id IS '所属审核单ID';
COMMENT ON COLUMN lift_confirmation.reviewer IS '审核员标识';
COMMENT ON COLUMN lift_confirmation.request_id IS '确认幂等请求标识';
