private record Effects(boolean closureCreated, int invalidated) {}

private Effects applyAnomalyIfNeeded(String areaId, int effectiveNewSnow, Instant now) {
    if (effectiveNewSnow <= NEW_SNOW_LIMIT_CM) return new Effects(false, 0);
    int invalidated = repo.invalidatePendingReviews(areaId, "NEW_OVER_LIMIT_READING", now);
    boolean created = false;
    if (repo.findOpenClosure(areaId).isEmpty()) {
        repo.insertClosure(areaId, "新增积雪超限(" + effectiveNewSnow + "cm)", now);
        created = true;
    }
    return new Effects(created, invalidated);
}
