public ServiceResult<CorrectionResponse> submitCorrection(String areaId, String hourUtc, CorrectionRequest req) {
    Instant hour = parseHour(hourUtc);
    Instant now = Instant.now(clock);
    repo.ensureArea(areaId, areaId, now);
    repo.lockArea(areaId);
    if (req.correctedSnowDepthCm() == null && req.correctedNewSnowCm() == null) {
        throw ApiException.unprocessable("EMPTY_CORRECTION", "勘误至少修正一项");
    }
    return idempotent("correction:" + areaId + ":" + hour, req.requestId(), ..., CorrectionResponse.class, () -> {
        Long readingId = repo.findReadingId(areaId, hour).orElseThrow(() -> ApiException.notFound("READING_NOT_FOUND", "该整点读数不存在"));
        long id = repo.insertCorrection(readingId, req.correctedSnowDepthCm(), req.correctedNewSnowCm(), req.reviewer(), req.note(), req.requestId(), now);
        Effects effects = req.correctedNewSnowCm() == null ? new Effects(false, 0) : applyAnomalyIfNeeded(areaId, req.correctedNewSnowCm(), now);
        return new ServiceResult<>(201, new CorrectionResponse(id, readingId, effects.closureCreated(), effects.invalidated()));
    });
}
