private List<SnowRepository.WindowRow> validateWindow(String areaId, List<Instant> hours) {
    List<WindowRow> rows = repo.findWindowRows(areaId, hours);
    if (rows.size() < hours.size()) {
        throw ApiException.unprocessable("MISSING_HOURLY_READINGS", "最近连续3个整点读数不完整");
