    for (WindowRow row : rows) {
        if (row.effectiveNewSnowCm() > NEW_SNOW_LIMIT_CM) {
            throw ApiException.unprocessable("WINDOW_EXCEEDS_LIMIT", "窗口内存在超限新增积雪: " + row.hourUtc());
