private List<Instant> hoursBetween(Instant start, Instant end) {
    List<Instant> hours = new ArrayList<>();
    for (Instant h = start; !h.isAfter(end); h = h.plus(1, ChronoUnit.HOURS)) hours.add(h);
    return hours;
}
```

