@Transactional(readOnly = true)
public AreaStatusResponse getStatus(String areaId) {
    List<Instant> hours = windowHours();
    List<WindowRow> rows = repo.findWindowRows(areaId, hours);
    List<WindowReading> window = rows.stream().map(r -> new WindowReading(r.hourUtc().toString(), r.snowDepthCm(), r.newSnowCm(), r.effectiveNewSnowCm())).toList();
    boolean complete = rows.size() == hours.size();
    boolean within = complete && rows.stream().allMatch(r -> r.effectiveNewSnowCm() <= NEW_SNOW_LIMIT_CM);
    var openClosure = repo.findOpenClosure(areaId);
    String state = openClosure.isPresent() ? "CLOSED" : "OPEN";
    List<ReviewView> reviews = repo.listReviews(areaId).stream().map(r -> new ReviewView(r.id(), r.status(), repo.listReviewers(r.id()), r.invalidatedReason(), r.windowStart().toString(), r.windowEnd().toString(), r.readingsVersion())).toList();
    List<TimelineEvent> timeline = new ArrayList<>();
    for (ClosureRow c : repo.listClosures(areaId)) {
        timeline.add(new TimelineEvent("CLOSURE_OPENED", c.createdAt().toString(), c.reason()));
        if (c.closedAt() != null) timeline.add(new TimelineEvent("CLOSURE_LIFTED", c.closedAt().toString(), "封闭命令#" + c.id() + " 解除"));
    }
    for (DecisionRow d : repo.listDecisions(areaId)) {
        timeline.add(new TimelineEvent("LIFT_DECIDED", d.effectiveAt().toString(), "解除版本 v" + d.version() + " 审核单#" + d.reviewId()));
    }
    timeline.sort(Comparator.comparing(TimelineEvent::at));
    return new AreaStatusResponse(areaId, state, openClosure.map(ClosureRow::id).orElse(null), complete, within, window, reviews, timeline);
}
