@Transactional
public ServiceResult<ReviewResponse> confirm(String areaId, long reviewId, ConfirmationRequest req) {
    Instant now = Instant.now(clock);
    repo.ensureArea(areaId, areaId, now);
    repo.lockArea(areaId);
    return idempotent("confirm:" + reviewId, req.requestId(), reviewId + "|" + req.reviewer(), ReviewResponse.class, () -> {
        ReviewRow review = repo.findReview(reviewId).orElseThrow(() -> ApiException.notFound("REVIEW_NOT_FOUND", "审核单不存在"));
        if (!review.areaId().equals(areaId)) throw notFound...
        List<String> reviewers = repo.listReviewers(reviewId);
        if (reviewers.contains(req.reviewer())) {
            throw ApiException.conflict("DUPLICATE_REVIEWER", "同一审核员不可重复签字");
        }
        if (!"PENDING".equals(review.status())) {
            throw ApiException.conflict("REVIEW_NOT_PENDING", "审核单状态为 " + review.status());
        }
        long currentVersion = repo.countReadings(areaId);
        if (currentVersion != review.readingsVersion()) {
            repo.updateReviewStatus(reviewId, "INVALIDATED", "READINGS_VERSION_CONFLICT", now);
            throw ApiException.conflict("READINGS_VERSION_CONFLICT", "读数版本已变化，审核失效");
        }
        // 复核窗口仍然合规
        try {
            validateWindow(areaId, hours from review.windowStart..windowEnd);
        } catch (ApiException e) {
            repo.updateReviewStatus(reviewId, "INVALIDATED", e.getCode(), now);
            throw e;
        }
        // 区域仍需处于封闭状态
        if (repo.findOpenClosure(areaId).isEmpty()) throw conflict AREA_NOT_CLOSED;
        repo.insertConfirmation(reviewId, req.reviewer(), req.requestId(), now);
        List<String> all = repo.listReviewers(reviewId);
        Long liftVersion = null;
        String status = "PENDING";
        if (all.size() >= 2) {
            long v = repo.nextLiftVersion(areaId);
            repo.insertDecision(areaId, reviewId, v, now);
            repo.updateReviewStatus(reviewId, "CONFIRMED", null, now);
            repo.closeOpenClosures(areaId, now);
            liftVersion = v;
            status = "CONFIRMED";
        }
        return new ServiceResult<>(200, new ReviewResponse(reviewId, status, all, liftVersion));
    });
}
